create table xxventuri.xxeba_sales_appointment (
    appointment_id       number not null enable,
    row_version_number   number,
    customer_id          number,
    appointment_type     varchar2(100 byte),
    appointment_date     timestamp(6),
    contact_address      varchar2(100 byte),
    appointment_purpose  varchar2(100 byte),
    created              timestamp(6) with local time zone,
    created_by           varchar2(50 byte),
    updated              timestamp(6) with local time zone,
    updated_by           varchar2(50 byte),
    contact_person       varchar2(50 byte),
    contact_location     varchar2(50 byte),
    comments             varchar2(100 byte),
    lead_id              number,
    opportunity_id       number,
    account              varchar2(50 byte),
    source               varchar2(20 byte),
    appointment_status   varchar2(20 byte),
    status_comments      nvarchar2(50),
    contact_id           number,
    contact_person_id    number,
    contact_location_id  number,
    schedule_upto        date,
    schedule_reference   varchar2(500 byte),
    salesreps_id         number,
    customer_detail_id   number,
    schedule_change_date date,
    visited_on           date,
    created_temp         varchar2(100 byte),
    updated_temp         varchar2(100 byte)
);


